class CommonElements {
  public int[] solve(int[] arr1, int[] arr2) {
    int p1 = 0, p2 = 0;
    List<Integer> res = new ArrayList<>();
    while (p1 < arr1.length && p2 < arr2.length) {
      if (arr1[p1] == arr2[p2]) {
        res.add(arr1[p1]);
        p1++;
        p2++;
      } else if (arr1[p1] < arr2[p2]) {
        p1++;
      } else {
        p2++;
      }
    }
    return res.stream().mapToInt(i -> i).toArray();
  }
}

